import type { SessionUpdate } from "@linkshell/wire";

// Every kind of timeline row, for the dev-only gallery screen.

const WIDE = "";
const TALL = "";

const t0 = Date.now() - 3 * 3600_000;
let n = 0;
const at = (minutes: number) => t0 + minutes * 60_000;
const id = (prefix: string) => `${prefix}-${n++}`;

function timeline(updates: SessionUpdate[], start: number) {
  return applyEvents(
    emptyView("gallery"),
    updates.map((update, i) => ({ sessionId: "gallery", seq: i + 1, ts: start + i * 4000, update })),
  );
}

